(function () { "use strict"; function boot() { var c = document.getElementById("fireworks"); if (!c) return; var dpr = Math.max(1, window.devicePixelRatio || 1); var ctx = c.getContext("2d"); var W = 0, H = 0; var particles = []; function resize() { W = window.innerWidth; H = window.innerHeight; c.width = Math.floor(W * dpr); c.height = Math.floor(H * dpr); c.style.width = W + "px"; c.style.height = H + "px"; ctx.setTransform(dpr, 0, 0, dpr, 0, 0) } resize(); window.addEventListener("resize", resize, { passive: true }); function rand(a, b) { return a + Math.random() * (b - a) } function hsla(h, s, l, a) { return "hsla(" + h + "," + s + "%," + l + "%," + a + ")" } function spawn(x, y) { var count = 18 + Math.floor(Math.random() * 14); var base = rand(0, 360); for (var i = 0; i < count; i++) { var ang = rand(0, Math.PI * 2); var sp = rand(2.5, 6.5); particles.push({ x: x, y: y, vx: Math.cos(ang) * sp, vy: Math.sin(ang) * sp, ax: 0, ay: 0.06, life: 0, ttl: rand(40, 70), size: rand(1.2, 2.4), h: (base + rand(-30, 30) + 360) % 360 }) } } function tick() { ctx.clearRect(0, 0, W, H); for (var i = particles.length - 1; i >= 0; i--) { var p = particles[i]; p.vx += p.ax; p.vy += p.ay; p.x += p.vx; p.y += p.vy; p.life++; var t = p.life / p.ttl; var a = 1 - t; ctx.fillStyle = hsla(p.h, 90, 60, Math.max(0, a)); ctx.beginPath(); ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2); ctx.fill(); if (p.life >= p.ttl || p.x < -20 || p.x > W + 20 || p.y < -20 || p.y > H + 20) { particles.splice(i, 1) } } requestAnimationFrame(tick) } tick(); function onPointer(e) { var x = e.clientX, y = e.clientY; spawn(x, y) } window.addEventListener("pointerdown", onPointer, { passive: true }) } if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", boot, { once: true }); else boot() })();
